[CmdletBinding()]
param(
  [string]$InstallRoot = 'D:\yuanbai',
  [string]$SourcePath = 'D:\yuanbai\downloads\v8-20261018-104233\yuanbai_agent-430575c62863796573cbd5026a35095c144a109d',
  [switch]$ValidateOnly
)
$ErrorActionPreference = 'Stop'
$encoded = ''
$stream = [IO.MemoryStream]::new([Convert]::FromBase64String($encoded))
$gzip = [IO.Compression.GZipStream]::new($stream,[IO.Compression.CompressionMode]::Decompress)
$reader = [IO.StreamReader]::new($gzip,[Text.Encoding]::UTF8)
try { $files = @($reader.ReadToEnd() | ConvertFrom-Json) } finally { $reader.Dispose(); $stream.Dispose() }
$SourcePath = [IO.Path]::GetFullPath($SourcePath).TrimEnd('\')
$live = Join-Path $InstallRoot 'public'
if (!(Test-Path -LiteralPath (Join-Path $SourcePath 'node_modules\vite\package.json'))) { throw 'Existing V8 source and dependencies not found. Pass -SourcePath with the deployed source directory.' }
function Hash-Bytes([byte[]]$Bytes) {
  $algorithm = [Security.Cryptography.SHA256]::Create()
  try { return ([BitConverter]::ToString($algorithm.ComputeHash($Bytes))).Replace('-','').ToLowerInvariant() } finally { $algorithm.Dispose() }
}
foreach ($item in $files) {
  $target = [IO.Path]::GetFullPath((Join-Path $SourcePath $item.path))
  if (!$target.StartsWith($SourcePath+'\',[StringComparison]::OrdinalIgnoreCase)) { throw 'Unsafe patch path.' }
  if ((Hash-Bytes ([Convert]::FromBase64String($item.content))) -ne $item.sha256) { throw "Invalid patch: $($item.path)" }
  if (Test-Path -LiteralPath $target) {
    $actual = (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($actual -ne $item.base -and $actual -ne $item.sha256) { throw "Local file differs from V8: $($item.path). No files changed." }
  } elseif ($item.base) { throw "Missing source file: $($item.path)" }
}
if ($ValidateOnly) { Write-Host "Validated $($files.Count) patch files; nothing changed."; return }
$entries = @('index.html','explore\index.html','dialogue\index.html')
foreach ($entry in $entries) {
  if (!(Test-Path -LiteralPath (Join-Path $live $entry))) { throw "Missing live page: $entry" }
}
$backup = Join-Path $InstallRoot ('backups\mobile-fix-'+(Get-Date -Format 'yyyyMMdd-HHmmss-fff'))
New-Item -ItemType Directory -Path $backup -Force | Out-Null
foreach ($item in $files) {
  $target = Join-Path $SourcePath $item.path
  if (Test-Path -LiteralPath $target) {
    $saved = Join-Path (Join-Path $backup 'source') $item.path
    New-Item -ItemType Directory -Path (Split-Path $saved -Parent) -Force | Out-Null
    Copy-Item -LiteralPath $target -Destination $saved
  }
  New-Item -ItemType Directory -Path (Split-Path $target -Parent) -Force | Out-Null
  [IO.File]::WriteAllBytes($target,[Convert]::FromBase64String($item.content))
}
Push-Location $SourcePath
$pagesTouched = $false
try {
  Write-Host '1/3 Build frontend. Live pages remain available.'
  & npm.cmd run school:build
  if ($LASTEXITCODE -ne 0) { throw 'Build failed; live pages were not changed.' }
  & node.exe --test tests/scene-failure.test.mjs school/tests/module-identity.test.mjs
  if ($LASTEXITCODE -ne 0) { throw 'Scene failure tests failed; live pages were not changed.' }
  foreach ($entry in $entries) {
    $saved = Join-Path (Join-Path $backup 'public') $entry
    New-Item -ItemType Directory -Path (Split-Path $saved -Parent) -Force | Out-Null
    Copy-Item -LiteralPath (Join-Path $live $entry) -Destination $saved
  }
  Write-Host '2/3 Copy versioned assets, retaining existing assets for cached pages.'
  & robocopy.exe (Join-Path $SourcePath 'dist-school\public\assets') (Join-Path $live 'assets') /E /R:2 /W:1 /NFL /NDL /NJH /NJS /NP | Out-Host
  if ($LASTEXITCODE -ge 8) { throw 'Asset copy failed; live entry pages were not changed.' }
  $built = Join-Path $SourcePath 'dist-school\public'
  foreach ($asset in Get-ChildItem -LiteralPath (Join-Path $built 'assets') -File) {
    $copy = Join-Path (Join-Path $live 'assets') $asset.Name
    if ((Get-FileHash -LiteralPath $asset.FullName).Hash -ne (Get-FileHash -LiteralPath $copy).Hash) { throw "Asset verification failed: $($asset.Name)" }
  }
  Write-Host '3/3 Publish and verify the three entry pages.'
  $pagesTouched = $true
  foreach ($entry in $entries) {
    Copy-Item -LiteralPath (Join-Path $built $entry) -Destination (Join-Path $live $entry) -Force
    if ((Get-FileHash -LiteralPath (Join-Path $built $entry)).Hash -ne (Get-FileHash -LiteralPath (Join-Path $live $entry)).Hash) { throw "Page verification failed: $entry" }
  }
  Write-Host "Mobile frontend hotfix deployed. Backup: $backup"
  Write-Host 'Test normal mode and /yuanbai/dialogue/?view=lite on the phone.'
  Write-Host 'Agent remains school-v8. Nginx, services, database and keys were not changed.'
} catch {
  $failure = $_
  if ($pagesTouched) {
    foreach ($entry in $entries) {
      Copy-Item -LiteralPath (Join-Path (Join-Path $backup 'public') $entry) -Destination (Join-Path $live $entry) -Force
    }
    Write-Host 'Previous entry pages restored.'
  }
  throw $failure
} finally { Pop-Location }
